import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

const VibrantDemo = () => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // Custom Cursor Logic
  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="relative min-h-screen bg-[#0a0a0c] text-white overflow-hidden p-10 font-sans">
      
      {/* 1. ANIMATED CURSOR GLOW */}
      <div 
        className="pointer-events-none fixed inset-0 z-50 transition-opacity duration-300"
        style={{
          background: `radial-gradient(600px at ${mousePos.x}px ${mousePos.y}px, rgba(139, 92, 246, 0.15), transparent 80%)`
        }}
      />

      {/* 2. VIBRANT HERO TEXT */}
      <div className="text-center mt-20">
        <motion.h1 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-7xl font-extrabold tracking-tighter"
        >
          Unique <span className="bg-gradient-to-r from-cyan-400 via-purple-500 to-red-500 bg-clip-text text-transparent">Vibrant RGB</span>
        </motion.h1>
        <p className="text-gray-400 mt-4 text-lg">Professional • Aesthetic • High-Performance</p>
      </div>

      {/* 3. ACHIEVEMENT / MEMORIES CARDS (Glassmorphism) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-24">
        {[1, 2, 3].map((i) => (
          <motion.div 
            key={i}
            whileHover={{ scale: 1.05, borderColor: 'rgba(255,255,255,0.5)' }}
            className="p-8 rounded-3xl bg-white/5 border border-white/10 backdrop-blur-xl transition-all shadow-2xl relative group overflow-hidden"
          >
            {/* Hover Glow Effect */}
            <div className="absolute -inset-1 bg-gradient-to-r from-red-600 to-purple-600 rounded-3xl blur opacity-0 group-hover:opacity-20 transition duration-500"></div>
            
            <h3 className="text-2xl font-bold mb-2">Memory 0{i}</h3>
            <p className="text-gray-400">Successfully integrated with premium RGBRO styling without changing core logic.</p>
            <div className="mt-6 h-1 w-12 bg-cyan-500 rounded-full"></div>
          </motion.div>
        ))}
      </div>

      {/* 4. BACKGROUND DECORATION */}
      <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] bg-purple-900/20 rounded-full blur-[120px]" />
      <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-900/20 rounded-full blur-[120px]" />
    </div>
  );
};

export default VibrantDemo;
